using System;
using System.Collections.Generic;
using UnityEngine;
using Kamilunavo.RepairEmpire.Visuals;
// Structural/render-budget contracts. Concept fidelity still requires actual root photographs.
public static class RepairConceptPolishValidation {
 static int checks;
 static void Check(bool value,string label){checks++;if(!value)throw new InvalidOperationException("Repair concept polish: "+label);}
 static string Point(Vector3 p)=>Mathf.RoundToInt(p.x*100000)+","+Mathf.RoundToInt(p.y*100000)+","+Mathf.RoundToInt(p.z*100000);
 static int OpenEdges(Mesh mesh){var vertices=mesh.vertices;var edges=new Dictionary<string,int>();var triangles=mesh.triangles;for(int i=0;i<triangles.Length;i+=3)for(int j=0;j<3;j++){string a=Point(vertices[triangles[i+j]]),b=Point(vertices[triangles[i+(j+1)%3]]);string edge=string.CompareOrdinal(a,b)<0?a+"/"+b:b+"/"+a;edges.TryGetValue(edge,out int count);edges[edge]=count+1;}int open=0;foreach(var count in edges.Values)if(count!=2)open++;return open;}
 static void Collect(GameObject root,HashSet<UnityEngine.Object> assets){foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){assets.Add(f.sharedMesh);foreach(var v in f.sharedMesh.vertices)Check(float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z),"finite authored vertices");foreach(var n in f.sharedMesh.normals)Check(n.sqrMagnitude>.5f,"valid authored lighting normals");}foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){var m=r.sharedMaterial;if(m!=null&&(m.name.StartsWith("FixturePBR")||m.name.StartsWith("Van")||m.name.StartsWith("Urban"))){assets.Add(m);if(m.mainTexture!=null)assets.Add(m.mainTexture);}}foreach(var p in root.GetComponentsInChildren<ReflectionProbe>(true))if(p.customBakedTexture!=null)assets.Add(p.customBakedTexture);}
 public static void Validate(){checks=0;var assets=new HashSet<UnityEngine.Object>();var host=new GameObject("Concept fixture polish");try{var fixture=ServiceSceneArt.BuildFixture(host.transform,"faucet",1,2);var spout=fixture.transform.Find("Service fixture/Curved chrome spout").GetComponent<MeshFilter>().sharedMesh;Check(OpenEdges(spout)==0,"faucet spout is a sealed solid volume, without open tube ends");Check(spout.vertexCount>=600&&spout.vertexCount<2000,"continuous faucet bend has bounded fine geometry");var chrome=FixtureMaterials.Get(fixture.transform,FixtureFinish.Chrome);Check(chrome.GetFloat("_Metallic")>=.9f&&chrome.GetFloat("_Glossiness")>=.85f&&!chrome.IsKeywordEnabled("_EMISSION"),"chrome uses reflected/specular light rather than luminous paint");var cube=FixtureMaterials.Kit(fixture.transform).Environment();assets.Add(cube);Check(cube.width<=64&&cube.format==TextureFormat.RGBAHalf,"finite local HDR environment preserves bright physical highlights");Check(fixture.GetComponentsInChildren<Collider>(true).Length==0,"fixture remains non-colliding");Collect(host,assets);}finally{UnityEngine.Object.DestroyImmediate(host);}foreach(var asset in assets)Check(asset==null,"fixture geometry/material/environment owned cleanup");
  assets.Clear();var van=new GameObject("Concept van polish",typeof(VanArt));try{van.GetComponent<VanArt>().Build();Check(van.transform.Find("Rear sculpted cargo door").GetComponent<MeshFilter>().sharedMesh.vertexCount>=128,"rear cargo panel has an authored rounded perimeter");var rearDoor=van.transform.Find("Rear sculpted cargo door");var rearWindow=van.transform.Find("Rear window left");Check(rearWindow.localPosition.z+rearWindow.GetComponent<MeshFilter>().sharedMesh.bounds.min.z<rearDoor.localPosition.z+rearDoor.GetComponent<MeshFilter>().sharedMesh.bounds.min.z,"rear glazing remains in front of rounded cargo skin");var seal=van.transform.Find("Rear window seal");float sealFace=seal.localPosition.z+seal.GetComponent<MeshFilter>().sharedMesh.bounds.min.z;float doorFace=rearDoor.localPosition.z+rearDoor.GetComponent<MeshFilter>().sharedMesh.bounds.min.z;float glassFace=rearWindow.localPosition.z+rearWindow.GetComponent<MeshFilter>().sharedMesh.bounds.min.z;Check(sealFace<doorFace-.003f&&sealFace>glassFace+.003f,"window seal has stable depth separation between door and glass");Check(van.GetComponentsInChildren<Collider>(true).Length==0,"van polish adds no collision");int count=0,vertices=0;var meshes=new HashSet<Mesh>();foreach(var r in van.GetComponentsInChildren<MeshRenderer>())if(r.enabled)count++;foreach(var f in van.GetComponentsInChildren<MeshFilter>())if(meshes.Add(f.sharedMesh))vertices+=f.sharedMesh.vertexCount;Check(count<=32&&vertices<70000,"hero van retains existing mobile renderer and buffer ceilings");Collect(van,assets);}finally{UnityEngine.Object.DestroyImmediate(van);}foreach(var asset in assets)Check(asset==null,"van reflection/material/buffer owned cleanup");
  assets.Clear();var district=new GameObject("Concept residential facade");try{var stone=new Material(Resources.Load<Material>("Materials/Surface"));var glass=new Material(stone);var metal=new Material(stone);ArtLifetime.Own(district,stone);ArtLifetime.Own(district,glass);ArtLifetime.Own(district,metal);assets.Add(stone);assets.Add(glass);assets.Add(metal);var kit=new UrbanArtKit(district.transform,stone,glass,metal);kit.Facade(18,50,15,10,17,-1,0);kit.Tree(new Vector3(11.2f,0,32),metal);bool residential=false,arched=false;foreach(var f in district.GetComponentsInChildren<MeshFilter>()){if(f.name=="Deeply recessed urban glazing"&&f.transform.localPosition.y>4){Check(f.sharedMesh.bounds.size.x<=1.6f,"residential upper windows leave substantial masonry between bays");residential=true;}if(f.name=="Residential arch voussoir")arched=true;}Check(residential&&arched,"historic frontage has narrow recessed windows and masonry arches");Check(district.GetComponentsInChildren<Collider>(true).Length==0,"frontage and planting add no collision");Collect(district,assets);}finally{UnityEngine.Object.DestroyImmediate(district);}foreach(var asset in assets)Check(asset==null,"district kit/material/buffer owned cleanup");Debug.Log("REPAIR_CONCEPT_POLISH_PASS checks="+checks);}
}
#endif
